typealias Step = @Sendable (Envelope) async throws -> Envelope

func advance(_ env: Envelope, steps: [String: Step]) async throws -> Envelope {
    var env = env
    while env.cursor < env.slip.count {
        guard let step = steps[env.slip[env.cursor]] else { throw SlipError.unknownStep }
        env = try await step(env)
        env.cursor += 1
    }
    return env
}
